function showCanvasContextMenu(x,y){hideMenus();const items=[['plus','添加节点','add'],['arrows-maximize','适配画布','fit'],['capture','选择工具','select'],['hand-stop','抓手工具','pan'],['folders','素材管理','assets'],['list-details','时间线','timeline']];els.nodeContextMenu.innerHTML=items.map(([i,t,a])=>`<button class="context-menu-item" data-context-action="${a}">${icon(i)}<span>${t}</span></button>`).join('');$$('[data-context-action]',els.nodeContextMenu).forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.contextAction;hideMenus();if(a==='add')showNodeMenu(x,y,screenToWorld(x,y));else if(a==='fit')fitCanvas();else if(a==='select'||a==='pan')setTool(a);else if(a==='assets')showDrawer('assetDrawer');else if(a==='timeline')setTimelineOpen(true);}));menuPosition(els.nodeContextMenu,x,y);}
function duplicateNode(n){beginCanvasSnapshot();const c=clone(n);c.id=id();c.position={x:n.position.x+36,y:n.position.y+36};c.data={...c.data,status:'idle',progress:0,jobId:null,error:''};S.workflow.nodes.push(c);S.selectedNodeId=c.id;S.selectedNodeIds=[c.id];scheduleSave();renderCanvas();renderEdges();renderInspector();}
